/**********************************
* dailycoding -20210920 / graphic
* by E.C.H (Eiichi Ishii)
**********************************/

let pg, msk, dis, g;

function setup() {
  createCanvas((w = windowHeight), w);
  noLoop();

  g = w / 10;
}

function draw() {
  background(255);

  pg = createGraphics(w, w);
  pg.rectMode(CENTER);
  pg.background(255);

  for (let x = g / 2; x <= w - g / 2; x += g) {
    for (let y = g / 2; y <= w - g / 2; y += g) {
      pg.push();
      pg.translate(x, y);

      let vg = int(random(1, 40));
      let sg = g / vg;

      for (let sx = -g / 2 + sg / 2; sx <= g / 2 - sg / 2; sx += sg) {
        for (let sy = -g / 2 + sg / 2; sy <= g / 2 - sg / 2; sy += sg) {
          pg.stroke(0);
          pg.strokeWeight(random(1, sg));
          pg.point(sx + random(-g / 2, g / 2), sy + random(-g / 2, g / 2));
        }
      }
      pg.pop();
    }
  }

  msk = createGraphics(w, w);
  msk.angleMode(DEGREES);
  msk.stroke(255);
  msk.noFill();
  let cr = w / 1.2;

  for (let h = 0; h < 4; h++) {
    msk.push();
    msk.translate(w / 2, w / 2);
    msk.rotate(random(360));
    msk.drawingContext.shadowOffsetX = random(-cr / 30, cr / 30);
    msk.drawingContext.shadowOffsetY = random(cr / 30, cr / 30);
    msk.drawingContext.shadowBlur = 10;
    msk.drawingContext.shadowColor = "black";
    msk.strokeWeight(random(1, w / 20));
    msk.beginShape();
    for (let i = 0; i <= 8; i++) {
      let angle = random(360);
      msk.curveVertex((cr / 2) * cos(angle), (cr / 2) * sin(angle));
    }
    msk.endShape();
    msk.pop();
  }

  (dis = pg.get()).mask(msk);

  filter(INVERT);
  image(pg, 0, 0, w, w);
  filter(INVERT);
  image(dis, 0, 0, w, w);
}

function keyPressed() {
  redraw();
}

